const input = $input.first().json;
const siteUrl = $env.SHAREPOINT_SITE_URL;
const listName = input.listName || 'Presales';

if (!siteUrl) throw new Error('SHAREPOINT_SITE_URL env var is required');

const withoutProtocol = siteUrl.replace(/^https?:\/\//i, '');
const firstSlash = withoutProtocol.indexOf('/');
const hostname = firstSlash === -1 ? withoutProtocol : withoutProtocol.substring(0, firstSlash);
const serverPath = firstSlash === -1 ? '' : withoutProtocol.substring(firstSlash).replace(/\/+$/, '');
const siteRef = `${hostname}:${serverPath}:`;

const operation = input.operation;
let method, url, bodyData;

const rawFields = input.fields
  ? (typeof input.fields === 'string' ? JSON.parse(input.fields) : input.fields)
  : {};

if (operation === 'get') {
  method = 'GET';
  url = `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteRef)}/lists/${listName}/items/${encodeURIComponent(String(input.itemId))}/fields`;
  bodyData = null;
} else if (operation === 'create') {
  method = 'POST';
  url = `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteRef)}/lists/${listName}/items`;
  bodyData = { fields: rawFields };
} else if (operation === 'update') {
  method = 'PATCH';
  url = `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteRef)}/lists/${listName}/items/${encodeURIComponent(String(input.itemId))}/fields`;
  bodyData = rawFields;
} else {
  return [{
    json: {
      success: false,
      operation,
      error: `Unknown operation: "${operation}". Use "get", "create", or "update".`
    }
  }];
}

let response;
try {
  const reqOptions = {
    method,
    url,
    headers: bodyData && method !== 'GET' ? { 'Content-Type': 'application/json' } : {},
    json: true,
    returnFullResponse: false,
  };
  if (bodyData && method !== 'GET') reqOptions.body = bodyData;
  response = await this.helpers.httpRequestWithAuthentication('oAuth2Api', reqOptions);
} catch (error) {
  const errMsg = error.message || error.description || String(error);
  return [{ json: { success: false, operation, error: errMsg.slice(0, 500) } }];
}

if (operation === 'get') {
  return [{
    json: {
      success: true,
      operation,
      itemId: response.id || null,
      fields: response,
      webUrl: response.webUrl || null
    }
  }];
}

const resultFields = response.fields || response;
return [{
  json: {
    success: true,
    operation,
    itemId: response.id || null,
    fields: resultFields,
    webUrl: resultFields.webUrl || null
  }
}];
